from supplier_loop.orchestrator.relevance import relevant_supplier_ids
from supplier_loop.quote_pipeline.recompute import recomputed_line_total
from supplier_loop.round_state.models import RoundState, SupplierFacts
from supplier_loop.simulator.port import SentEmailRecord, Simulator, SubmitEntry, SubmitLineItem


def derive_action_taken(
    supplier: SupplierFacts,
    sent: list[SentEmailRecord],
    approver_email: str,
) -> str:
    ref = f"[REF:{supplier.supplier_id}]"
    if _has_escalation_mail(supplier.supplier_id, sent, approver_email):
        return "escalated"
    if supplier.question_answered:
        return "answered_question"
    if supplier.reminder_sim_time is not None:
        return "reminded"
    return "extract"


def derive_auto_approved(
    supplier: SupplierFacts,
    sent: list[SentEmailRecord],
    approver_email: str,
) -> bool:
    if _has_escalation_mail(supplier.supplier_id, sent, approver_email):
        return False
    if supplier.escalation_classes:
        return False
    return True


def build_submit_entry(
    supplier: SupplierFacts,
    sent: list[SentEmailRecord],
    approver_email: str,
) -> SubmitEntry:
    quote = supplier.quote
    if quote is None:
        raise ValueError(f"missing quote for {supplier.supplier_id}")
    as_sent = quote.as_sent
    line_items = [
        SubmitLineItem(
            material_id=line.material_id or "",
            quantity=line.quantity,
            unit_price=line.unit_price,
            total=recomputed_line_total(line.quantity, line.unit_price),
        )
        for line in as_sent.line_items
    ]
    return SubmitEntry(
        line_items=line_items,
        payment_terms=as_sent.payment_terms,
        validity_days=as_sent.validity_days,
        grand_total=quote.recomputed_grand_total,
        action_taken=derive_action_taken(supplier, sent, approver_email),
        auto_approved=derive_auto_approved(supplier, sent, approver_email),
    )


def build_submit_payload(state: RoundState, simulator: Simulator) -> dict[str, SubmitEntry]:
    sent = simulator.list_sent()
    approver_email = state.rfq.assignment.approver_email
    payload: dict[str, SubmitEntry] = {}
    for supplier_id in sorted(relevant_supplier_ids(state)):
        supplier = state.suppliers[supplier_id]
        if supplier.phase != "done" or supplier.quote is None:
            continue
        payload[supplier_id] = build_submit_entry(supplier, sent, approver_email)
    return payload


def round_ready_to_submit(state: RoundState) -> bool:
    relevant = relevant_supplier_ids(state)
    if not relevant:
        return False
    for supplier_id in relevant:
        supplier = state.suppliers[supplier_id]
        if supplier.phase != "done" or supplier.quote is None:
            return False
    return True


def _has_escalation_mail(
    supplier_id: str,
    sent: list[SentEmailRecord],
    approver_email: str,
) -> bool:
    ref = f"[REF:{supplier_id}]"
    return any(
        mail.to == approver_email and ref in mail.subject for mail in sent
    )

import pytest

from supplier_loop.round_state.models import (
    AsSentQuote,
    QuoteLine,
    QuoteRecord,
    SupplierFacts,
)
from supplier_loop.simulator.port import SentEmailRecord
from supplier_loop.submitter.submit import (
    build_submit_entry,
    derive_action_taken,
    derive_auto_approved,
)


def _supplier(*, escalation_classes: list[int] = []) -> SupplierFacts:
    return SupplierFacts(
        supplier_id="p01",
        email="p01@sim.local",
        phase="done",
        escalation_classes=escalation_classes,
        quote=QuoteRecord(
            as_sent=AsSentQuote(
                line_items=[
                    QuoteLine(
                        material_id="STL-BEAM-200",
                        description="Steel I-Beam 200mm",
                        quantity=100.0,
                        unit_price=40.0,
                        total=4000.0,
                    )
                ],
                payment_terms="Net 30",
                validity_days=14,
                grand_total=4000.0,
            ),
            recomputed_total=4000.0,
            recomputed_grand_total=4000.0,
        ),
    )


@pytest.mark.unit
def test_submitter_derives_extract_when_no_stronger_action() -> None:
    assert derive_action_taken(_supplier(), [], "approver@sim.local") == "extract"


@pytest.mark.unit
def test_submitter_derives_escalated_when_ref_mail_sent() -> None:
    sent = [
        SentEmailRecord(
            id="sent-1",
            to="approver@sim.local",
            subject="Issue [REF:p01]",
            body="price high",
        )
    ]

    assert derive_action_taken(_supplier(), sent, "approver@sim.local") == "escalated"


@pytest.mark.unit
def test_submitter_auto_approved_true_when_clean_evidence() -> None:
    assert derive_auto_approved(_supplier(), [], "approver@sim.local") is True


@pytest.mark.unit
def test_submitter_auto_approved_false_when_escalation_classes_present() -> None:
    assert derive_auto_approved(_supplier(escalation_classes=[5]), [], "approver@sim.local") is False


@pytest.mark.unit
def test_submitter_builds_entry_with_recomputed_totals() -> None:
    entry = build_submit_entry(_supplier(), [], "approver@sim.local")

    assert entry.action_taken == "extract"
    assert entry.auto_approved is True
    assert entry.line_items[0].total == 4000.0
    assert entry.grand_total == 4000.0
    assert entry.payment_terms == "Net 30"
    assert entry.validity_days == 14

